'use strict';
globalThis.LearningVisuals=(()=>{
 const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=id=>document.getElementById(id);
 let current=null,flowIndex=0,paperIndex=0;
 let attention={query:3,temperature:1,causal:true},train={w:1,rate:.15,history:[1]},horizon=3,frames=8,depth=1;
 const scores=[[2,.2,.4,.1],[1.2,1.8,.5,.6],[.4,.6,2,1.2],[.3,1.1,2.2,1.5]],tokens=['机器人','拿起','红色','杯子'];
 function weights(row,temperature=1,causal=true){const s=scores[row].map((v,j)=>causal&&j>row?-Infinity:v/temperature),max=Math.max(...s),exp=s.map(v=>Math.exp(v-max)),sum=exp.reduce((a,b)=>a+b,0);return exp.map(v=>v/sum);}
 function trainStep(w,rate){return (1-10*rate)*w;}
 function samples(n){return Array.from({length:n},(_,i)=>6*i/(n-1));}
 function project(z){return {u:320+400*.2/z,v:240+400*.1/z};}
 function flowDetail(k,i){const s=k.flow.steps[i];return `<div class="flow-detail-title"><span>${String(i+1).padStart(2,'0')}</span><h3>${h(s.label)}</h3></div><dl class="flow-io"><div><dt>输入</dt><dd>${h(s.input)}</dd></div><div><dt>这一站做什么</dt><dd>${h(s.operation)}</dd></div><div><dt>输出到下一站</dt><dd>${h(s.output)}</dd></div></dl>`;}
 function flowButtons(){return current.flow.steps.map((s,i)=>`<li><button type="button" data-flow-step="${i}" aria-pressed="${i===flowIndex}" aria-controls="flow-reading" class="${i===flowIndex?'active':''}"><span class="flow-number">${String(i+1).padStart(2,'0')}</span><strong>${h(s.label)}</strong><small>${h(s.output)}</small></button></li>`).join('');}
 function overview(k){current=k;flowIndex=0;paperIndex=0;attention={query:3,temperature:1,causal:true};train={w:1,rate:.15,history:[1]};horizon=3;frames=8;depth=1;if(!k.flow)return '';return `<section id="guide-section-flow" class="visual-overview"><div class="visual-heading"><div><span class="visual-kicker">沿着数据理解</span><h2>${h(k.flow.title)}</h2></div><span class="visual-hint">点选任一步</span></div><ol id="flow-stages" class="flow-stages">${flowButtons()}</ol><div id="flow-reading" class="flow-reading" aria-live="polite">${flowDetail(k,0)}</div><p class="flow-caption">${h(k.flow.caption)}</p></section>`;}
 const paperLabels={'react':'ReAct · 推理与行动','toolformer':'Toolformer · 学习调用','reflexion':'Reflexion · 反思记忆','lats':'LATS · 行动树搜索','agentfold':'AgentFold · 上下文折叠','compactionrl':'CompactionRL · 训练摘要','toolverse':'ToolVerse · 工具环境与奖励','agent-scaling':'Agent Scaling · 协作评估','sonic':'SONIC · 通用运动控制','latent':'LATENT · 潜在技能与接球','adapt':'AdaPT · 速度适配','athlete':'ATHLETE · 反应式接球','dp3':'DP3 · 点云与动作','octo':'Octo · 模块化策略','rtx':'RT-X · 跨机器人学习','rma':'RMA · 历史适配','walk-minutes':'并行 PPO · 地形课程','grootn1':'GR00T N1 · 动作专家','pi0':'π0 · 连续动作流','mem':'MEM · 长短期记忆','blip2':'BLIP-2 · 视觉桥接','llava':'LLaVA · 视觉指令','qwen3-vl':'Qwen3-VL · 多层视觉','siglip2':'SigLIP 2 · 表征训练','ppo':'PPO · 裁剪目标','sac':'SAC · 训练算法','resnet':'ResNet · 残差连接','lora':'LoRA · 低秩更新','dpo':'DPO · 偏好训练','rag':'RAG · 检索与生成','chinchilla':'Chinchilla · 计算预算','mamba':'Mamba · 状态更新','dreamerv3':'DreamerV3 · 想象中学习','transformer-architecture':'Transformer · 编码与解码','ddpm':'DDPM · 加噪与去噪','act':'ACT · 动作块','diffusion-policy':'Diffusion Policy · 去噪','transformer':'注意力 · 信息汇集','clip':'CLIP · 图文配对','simclr':'SimCLR · 双视图','openvla':'OpenVLA · 视觉到动作','transfusion':'Transfusion · 联合训练','qwen2-vl':'Qwen2-VL · 视频输入'};
 function paperContent(){const figs=current.figures||[],f=figs[paperIndex];if(!f)return '';return `${figs.length>1?`<div class="paper-tabs" aria-label="选择论文图">${figs.map((p,i)=>`<button type="button" data-paper-tab="${i}" aria-pressed="${i===paperIndex}"><img src="${h(p.src)}" alt="" width="${p.width}" height="${p.height}" loading="lazy"><span>${h(paperLabels[p.id]||p.paperTitle)}</span></button>`).join('')}</div>`:''}<figure class="paper-figure"><button type="button" class="paper-image-button" data-paper-zoom="${paperIndex}" aria-label="放大：${h(f.alt)}"><img src="${h(f.src)}" alt="${h(f.alt)}" width="${f.width}" height="${f.height}" loading="lazy" decoding="async"><span>↗ 放大原图</span></button><figcaption><strong>${h(paperLabels[f.id]||f.paperTitle)} <span>${h(f.figure)}</span></strong><a href="${h(f.sourceUrl)}#page=${f.page}" target="_blank" rel="noopener noreferrer">${h(f.paperTitle)} ↗</a><small>${h(f.authors)} · ${h(f.year)} · 第 ${f.page} 页${f.version?' · '+h(f.version):''}</small></figcaption></figure>${f.context?`<p class="paper-context">${h(f.context)}</p>`:''}<ol class="paper-reading">${f.reading.map((s,i)=>`<li><span>${i+1}</span><p>${h(s)}</p></li>`).join('')}</ol>`;}
 function gallery(k){return k.figures?.length?`<section id="guide-section-paper" class="paper-gallery"><div class="visual-heading"><div><span class="visual-kicker">论文原图 + 中文读图</span><h2>从论文原图看方法</h2></div></div><div id="paper-content">${paperContent()}</div></section>`:'';}
 function inline(k,index){return (k.diagrams||[]).filter(d=>d.sectionIndex===index).map(d=>`<figure class="inline-diagram"><div class="diagram-viewport"><button type="button" data-diagram-zoom="${h(d.id)}" aria-label="放大图解：${h(d.title)}"><img src="${h(d.src)}" alt="${h(d.alt)}" width="${d.width}" height="${d.height}" loading="lazy" decoding="async"><span>↗ 放大图解</span></button></div><figcaption><strong>${h(d.title)}</strong><p>${h(d.caption)}</p></figcaption></figure>`).join('');}
 function labType(id){return {'gradient-training':'train','llm-token-attention':'attention','action-policy-handbook':'horizon','multimodal-video':'video','camera-calibration':'projection'}[id];}
 function lab(k){const type=labType(k.id);if(!type)return '';const titles={train:'调一次学习率，看参数怎样移动',attention:'点一个词，看它从哪里读取信息',horizon:'预测多长，多久重新看一次？',video:'多取几帧，能多看见什么？',projection:'同一个物体，离相机更远会怎样？'};const controls={
 train:`<label for="lab-rate">学习率 <output id="lab-rate-value">0.15</output></label><input id="lab-rate" data-lab-control="rate" type="range" min=".02" max=".25" step=".01" value=".15"><div class="lab-buttons"><button type="button" id="lab-train-step" data-train-step>更新一步</button><button type="button" data-train-reset>重新开始</button></div>`,
 attention:`<div id="attention-query" class="lab-token-buttons">${tokens.map((t,i)=>`<button type="button" data-attention-query="${i}" aria-pressed="${i===3}">${t}</button>`).join('')}</div><label for="lab-temperature">分数温度 <output id="lab-temperature-value">1.0</output></label><input id="lab-temperature" data-lab-control="temperature" type="range" min=".3" max="2" step=".1" value="1"><label class="lab-checkbox"><input id="lab-causal" data-lab-control="causal" type="checkbox" checked> 只读取当前及之前的词</label>`,
 horizon:`<label for="lab-horizon">执行几步后重新观察 <output id="lab-horizon-value">3 步</output></label><input id="lab-horizon" data-lab-control="horizon" type="range" min="1" max="8" step="1" value="3">`,
 video:`<label for="lab-frames">6 秒内采样帧数 <output id="lab-frames-value">8 帧</output></label><input id="lab-frames" data-lab-control="frames" type="range" min="3" max="25" step="1" value="8">`,
 projection:`<label for="lab-depth">物体深度 Z <output id="lab-depth-value">1.0 m</output></label><input id="lab-depth" data-lab-control="depth" type="range" min=".5" max="4" step=".1" value="1">`
 };return `<section id="guide-section-visual" class="mechanism-lab"><div class="visual-heading"><div><span class="visual-kicker">动手看关系</span><h2>${titles[type]}</h2></div></div><div class="lab-controls">${controls[type]}</div><div id="visual-lab-output" class="lab-output" aria-live="polite"></div></section>`;}
 function svg(title,body,box='0 0 640 260'){return `<svg viewBox="${box}" role="img" aria-label="${h(title)}">${body}</svg>`;}
 function trainOutput(){const w=train.w,L=5*w*w,points=train.history.map((x,i)=>`${35+i*28},${225-Math.min(200,5*x*x*32)}`).join(' ');return svg('更新次数与损失变化',`<path d="M35 22V225H610" fill="none" stroke="#c5cfbd"/><text x="35" y="16" class="svg-label">损失 L = 5w²</text><text x="515" y="247" class="svg-label">参数更新次数 →</text>${[0,1,2,3,4,5,6].map(v=>`<text x="8" y="${229-v*32}" class="svg-tick">${v}</text>`).join('')}<polyline points="${points}" fill="none" stroke="#47735b" stroke-width="3"/>${train.history.map((x,i)=>`<circle cx="${35+i*28}" cy="${225-Math.min(200,5*x*x*32)}" r="4" fill="#b88042"/>`).join('')}`)+`<div class="lab-stats"><span>参数 w <b>${w.toFixed(4)}</b></span><span>当前损失 <b>${L.toFixed(4)}</b></span><span>每步乘数 <b>${(1-10*train.rate).toFixed(2)}</b></span></div><p class="lab-explanation">固定曲率为 10，更新为 w ← (1−10η)w。学习率小于 0.2 时逐渐收敛；超过 0.2 时振幅变大。图中纵轴显示 0–6.25，较大的损失显示在顶部，精确值见上方数字。</p>`;}
 function attentionOutput(){const a=weights(attention.query,attention.temperature,attention.causal);return `<div class="attention-result"><div class="selected-query"><small>当前查询 Q</small><strong>${tokens[attention.query]}</strong><span>按权重汇集各位置的 V →</span></div><div class="attention-bars">${a.map((v,i)=>`<div class="attention-bar"><span>${tokens[i]}</span><div><i style="width:${v*100}%"></i></div><b>${(v*100).toFixed(1)}%</b></div>`).join('')}</div></div><p class="lab-explanation">固定一组匹配分数，观察 softmax 如何分配读取权重。温度越低，权重越集中；打开因果掩码后，未来位置的权重为 0。各位置的权重之和为 100%。</p><div class="attention-heatmap" role="table" aria-label="全部查询位置的注意力权重"><div class="heat-row heat-head" role="row"><span>查询 ↓ / 读取 →</span>${tokens.map(t=>`<span>${t}</span>`).join('')}</div>${scores.map((_,r)=>`<div class="heat-row ${r===attention.query?'heat-selected':''}" role="row"><b>${tokens[r]}</b>${weights(r,attention.temperature,attention.causal).map(v=>`<span role="cell" style="background:rgba(79,123,92,${.05+.68*v});color:${v>.65?'#fff':'#35533c'}">${(v*100).toFixed(0)}%</span>`).join('')}</div>`).join('')}</div>`;}
 function horizonOutput(){return `<div class="horizon-observation"><span>当前图像 + 关节状态</span><b>↓ 条件动作生成</b></div><div class="horizon-grid">${Array.from({length:8},(_,i)=>`<div class="${i<horizon?'execute':'planned'}"><small>t + ${i}</small><strong>a${i+1}</strong><span>${i<horizon?'执行':'保留预测'}</span></div>`).join('')}</div><div class="feedback-strip">执行 ${horizon} 步 → 在 ${(horizon/50).toFixed(2)} 秒后取得新观测 → 重新生成 8 步动作</div><p class="lab-explanation">固定预测长度为 8、控制频率为 50 Hz。橙色表示本轮真正执行的动作，绿色表示其余预测。执行长度越短，新观测越早进入下一次决策，策略调用也越频繁。</p>`;}
 function videoOutput(){const s=samples(frames),hits=s.filter(t=>t>=2.4-1e-9&&t<=2.8+1e-9).length;return svg('六秒时间轴上的采样点与短事件',`<rect x="${40+2.4/6*560}" y="45" width="${.4/6*560}" height="125" fill="#ead0ab"/><text x="240" y="28" class="svg-label">短事件：2.4–2.8 秒</text><path d="M40 145H600" stroke="#96a88a" stroke-width="2"/>${s.map(t=>`<path d="M${40+t/6*560} 110v50" stroke="${t>=2.4-1e-9&&t<=2.8+1e-9?'#a76b2d':'#52765e'}" stroke-width="2"/><circle cx="${40+t/6*560}" cy="110" r="5" fill="#52765e"/>`).join('')}${[0,1,2,3,4,5,6].map(t=>`<text x="${36+t/6*560}" y="187" class="svg-tick">${t}s</text>`).join('')}`,'0 0 640 210')+`<div class="lab-stats"><span>采样间隔 <b>${(6/(frames-1)).toFixed(2)} 秒</b></span><span>落在事件内的帧 <b>${hits} 帧</b></span></div><p class="lab-explanation">这里采用包含首尾时刻的均匀取帧。短事件可能发生在两次采样之间；增加采样密度通常更容易覆盖它，同时也会增加视觉序列长度。</p>`;}
 function projectionOutput(){const p=project(depth),x=40+p.u*.75,y=15+p.v*.75;return svg('固定三维横向位置时，深度改变像素位置',`<rect x="40" y="15" width="480" height="360" fill="#f5f7f0" stroke="#b4c3a8"/><path d="M280 15V375M40 195H520" stroke="#d2dcc9" stroke-dasharray="4 4"/><circle cx="280" cy="195" r="4" fill="#809675"/><path d="M280 195L${x} ${y}" stroke="#bb8b4d"/><circle cx="${x}" cy="${y}" r="8" fill="#bb8b4d"/><text x="${x+12}" y="${y-10}" class="svg-label">物体点</text><text x="285" y="183" class="svg-tick">主点 (320,240)</text>`,'0 0 560 400')+`<div class="lab-stats"><span>像素 u <b>${p.u.toFixed(1)}</b></span><span>像素 v <b>${p.v.toFixed(1)}</b></span><span>深度 Z <b>${depth.toFixed(1)} m</b></span></div><p class="lab-explanation">固定 X=0.2 m、Y=0.1 m，焦距 400 px，主点 (320,240)，使用无畸变针孔模型。深度增大时，X/Z 与 Y/Z 变小，投影点靠近主点。</p>`;}
 function drawLab(){if(!current||!$('visual-lab-output'))return;const type=labType(current.id);$('visual-lab-output').innerHTML=({train:trainOutput,attention:attentionOutput,horizon:horizonOutput,video:videoOutput,projection:projectionOutput}[type])?.()||'';if(type==='train'&&$('lab-train-step')){$('lab-train-step').disabled=train.history.length>=21;$('lab-train-step').textContent=train.history.length>=21?'已更新 20 步':'更新一步';}}
 function mount(){drawLab();}
 function zoom(i){const f=current?.figures?.[i];if(!f)return;$('paper-dialog-title').textContent=paperLabels[f.id]||f.paperTitle;$('paper-dialog-image').setAttribute('src',f.src);$('paper-dialog-image').setAttribute('alt',f.alt);$('paper-dialog-source').setAttribute('href',f.sourceUrl+'#page='+f.page);$('paper-dialog-source').textContent=f.paperTitle+' · '+f.figure;$('paper-dialog').showModal();}
 function zoomDiagram(id){const d=current?.diagrams?.find(d=>d.id===id);if(!d)return;$('paper-dialog-title').textContent=d.title;$('paper-dialog-image').setAttribute('src',d.src);$('paper-dialog-image').setAttribute('alt',d.alt);$('paper-dialog-source').setAttribute('href',`#guide?id=${current.id}&section=core-${d.sectionIndex}`);$('paper-dialog-source').textContent='回到对应讲解 · '+d.caption;$('paper-dialog').showModal();}
 document.addEventListener('click',ev=>{
  let t=ev.target.closest('[data-flow-step]');if(t&&current){flowIndex=Number(t.dataset.flowStep);$('flow-stages').innerHTML=flowButtons();$('flow-reading').innerHTML=flowDetail(current,flowIndex);document.querySelector(`[data-flow-step="${flowIndex}"]`)?.focus();return;}
  t=ev.target.closest('[data-paper-tab]');if(t&&current){paperIndex=Number(t.dataset.paperTab);$('paper-content').innerHTML=paperContent();document.querySelector(`[data-paper-tab="${paperIndex}"]`)?.focus();return;}
  t=ev.target.closest('[data-paper-zoom]');if(t){zoom(Number(t.dataset.paperZoom));return;}
 t=ev.target.closest('[data-diagram-zoom]');if(t){zoomDiagram(t.dataset.diagramZoom);return;}
  if(ev.target.closest('[data-paper-close]')||ev.target.closest('#paper-dialog-source')?.getAttribute('href')?.startsWith('#guide')){$('paper-dialog').close();return;}
  t=ev.target.closest('[data-attention-query]');if(t){attention.query=Number(t.dataset.attentionQuery);document.querySelectorAll('[data-attention-query]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.attentionQuery)===attention.query));drawLab();return;}
  if(ev.target.closest('[data-train-step]')){if(train.history.length>=21)return;train.w=trainStep(train.w,train.rate);train.history.push(train.w);drawLab();return;}
  if(ev.target.closest('[data-train-reset]')){train.w=1;train.history=[1];drawLab();}
 });
 document.addEventListener('input',ev=>{const c=ev.target.dataset.labControl;if(!c)return;const n=Number(ev.target.value);if(c==='rate'){train.rate=n;train.w=1;train.history=[1];$('lab-rate-value').textContent=n.toFixed(2);}if(c==='temperature'){attention.temperature=n;$('lab-temperature-value').textContent=n.toFixed(1);}if(c==='causal')attention.causal=ev.target.checked;if(c==='horizon'){horizon=n;$('lab-horizon-value').textContent=n+' 步';}if(c==='frames'){frames=n;$('lab-frames-value').textContent=n+' 帧';}if(c==='depth'){depth=n;$('lab-depth-value').textContent=n.toFixed(1)+' m';}drawLab();});
 return {overview,gallery,inline,lab,mount,flowDetail,weights,trainStep,samples,project};
})();
